    fun of(exercise: Exercise): MuscleActivation = when(exercise) {
        Exercise.SQUAT -> MuscleActivation(listOf(Muscle.QUADRICEPS, Muscle.GLUTES), listOf(Muscle.ADDUCTORS, Muscle.CORE), listOf(MuscleDetail.QUADRICEPS, MuscleDetail.GLUTE_MAX), listOf(MuscleDetail.ADDUCTORS, MuscleDetail.RECTUS_ABDOMINIS, MuscleDetail.OBLIQUES), "https://www.nasm.org/workout-exercise-guidance" )
        Exercise.LEG_PRESS -> MuscleActivation(listOf(Muscle.QUADRICEPS), listOf(Muscle.GLUTES, Muscle.ADDUCTORS), listOf(MuscleDetail.QUADRICEPS), listOf(MuscleDetail.GLUTE_MAX, MuscleDetail.ADDUCTORS), "https://www.nasm.org/resource-center/exercise-library/leg-press" )
        Exercise.CHEST_PRESS -> MuscleActivation(listOf(Muscle.CHEST), listOf(Muscle.FRONT_DELTS, Muscle.TRICEPS), listOf(MuscleDetail.MID_LOWER_CHEST), listOf(MuscleDetail.FRONT_DELT, MuscleDetail.TRICEPS, MuscleDetail.UPPER_CHEST), "https://www.acefitness.org/resources/everyone/exercise-library/188/seated-chest-press/" )
        Exercise.ROW -> MuscleActivation(listOf(Muscle.LATS, Muscle.UPPER_BACK), listOf(Muscle.BICEPS, Muscle.REAR_DELTS), listOf(MuscleDetail.LATS, MuscleDetail.MID_BACK), listOf(MuscleDetail.BICEPS, MuscleDetail.REAR_DELT, MuscleDetail.FOREARMS), "https://www.acefitness.org/resources/everyone/exercise-library/48/seated-row/" )
        Exercise.LAT_PULLDOWN -> MuscleActivation(listOf(Muscle.LATS), listOf(Muscle.BICEPS, Muscle.UPPER_BACK, Muscle.REAR_DELTS), listOf(MuscleDetail.LATS), listOf(MuscleDetail.BICEPS, MuscleDetail.MID_BACK, MuscleDetail.REAR_DELT, MuscleDetail.FOREARMS), "https://www.acefitness.org/resources/pros/expert-articles/8944/a-back-to-school-program-an-evidence-based-approach-to-training-the-back/" )
        Exercise.HIP_HINGE -> MuscleActivation(listOf(Muscle.GLUTES, Muscle.HAMSTRINGS), listOf(Muscle.ERECTORS, Muscle.CORE), listOf(MuscleDetail.GLUTE_MAX, MuscleDetail.HAMSTRINGS), listOf(MuscleDetail.SPINAL_ERECTORS, MuscleDetail.RECTUS_ABDOMINIS, MuscleDetail.OBLIQUES), "https://www.nasm.org/workout-exercise-guidance" )
        Exercise.SHOULDER_PRESS -> MuscleActivation(listOf(Muscle.FRONT_DELTS), listOf(Muscle.TRICEPS, Muscle.UPPER_BACK, Muscle.CHEST), listOf(MuscleDetail.FRONT_DELT), listOf(MuscleDetail.TRICEPS, MuscleDetail.UPPER_TRAPS, MuscleDetail.SIDE_DELT, MuscleDetail.UPPER_CHEST), "https://www.nasm.org/workout-exercise-guidance" )
        Exercise.SPLIT_SQUAT -> MuscleActivation(listOf(Muscle.QUADRICEPS, Muscle.GLUTES), listOf(Muscle.ADDUCTORS, Muscle.CORE), listOf(MuscleDetail.QUADRICEPS, MuscleDetail.GLUTE_MAX), listOf(MuscleDetail.ADDUCTORS, MuscleDetail.RECTUS_ABDOMINIS, MuscleDetail.OBLIQUES, MuscleDetail.GLUTE_MED), "https://www.nasm.org/workout-exercise-guidance" )
        Exercise.GOBLET_SQUAT -> MuscleActivation(listOf(Muscle.QUADRICEPS, Muscle.GLUTES), listOf(Muscle.CORE, Muscle.ADDUCTORS, Muscle.ERECTORS), listOf(MuscleDetail.QUADRICEPS, MuscleDetail.GLUTE_MAX), listOf(MuscleDetail.RECTUS_ABDOMINIS, MuscleDetail.OBLIQUES, MuscleDetail.ADDUCTORS, MuscleDetail.SPINAL_ERECTORS), "https://www.nasm.org/resource-center/exercise-library/goblet-squat" )
